const { chromium } = require('D:/Atharva/video-studio/node_modules/playwright-core');
const fs = require('fs');
const out = process.argv[2];
const sites = process.argv.slice(3);
(async () => {
  const b = await chromium.launch({ channel: 'msedge', headless: true });
  const ctx = await b.newContext({ viewport: { width: 1440, height: 900 }, colorScheme: 'dark' });
  for (const u of sites) {
    const name = u.replace(/https?:\/\//, '').replace(/[^a-z0-9]+/gi, '_').slice(0, 40);
    const p = await ctx.newPage();
    try {
      await p.goto(u, { waitUntil: 'domcontentloaded', timeout: 30000 });
      await p.waitForTimeout(4500);
      await p.screenshot({ path: `${out}/${name}.png` });
      const info = await p.evaluate(() => {
        const res = [];
        const els = [...document.querySelectorAll('body *')].slice(0, 4000);
        for (const e of els) {
          const r = e.getBoundingClientRect();
          if (r.top > 900 || r.bottom < 0 || r.width < 200 || r.height < 120) continue;
          const s = getComputedStyle(e);
          const bits = [];
          if (s.backgroundImage && s.backgroundImage !== 'none' && !s.backgroundImage.startsWith('url("data:image/svg+xml')) bits.push('bg:' + s.backgroundImage.slice(0, 380));
          else if (s.backgroundImage.startsWith('url("data:image/svg+xml')) bits.push('bg:svg-data ' + s.backgroundImage.length);
          if (s.maskImage && s.maskImage !== 'none') bits.push('mask:' + s.maskImage.slice(0, 200));
          if (s.filter && s.filter !== 'none') bits.push('filter:' + s.filter);
          if (s.mixBlendMode !== 'normal') bits.push('blend:' + s.mixBlendMode);
          if (s.animationName && s.animationName !== 'none') bits.push('anim:' + s.animationName + ' ' + s.animationDuration);
          if (e.tagName === 'CANVAS' || e.tagName === 'VIDEO') bits.push(e.tagName + (e.tagName === 'CANVAS' ? (e.getContext ? '' : '') : ' ' + (e.currentSrc || '')));
          if (bits.length) res.push(`${e.tagName.toLowerCase()}.${(e.className && e.className.baseVal === undefined ? e.className : '').toString().slice(0, 60)} [${Math.round(r.width)}x${Math.round(r.height)}@${Math.round(r.left)},${Math.round(r.top)}] ` + bits.join(' | '));
        }
        return { bodyBg: getComputedStyle(document.body).backgroundColor, n: res.length, res: res.slice(0, 40) };
      });
      fs.writeFileSync(`${out}/${name}.txt`, u + '\n' + JSON.stringify(info, null, 1));
      console.log('ok', u, info.n);
    } catch (e) { console.log('fail', u, e.message.slice(0, 120)); }
    await p.close();
  }
  await b.close();
})();

