// Measure and screenshot the hero at each size.
// usage: node shoot.js <outdir> <url> [tag] [sizes...]   sizes like 1440x900
const { chromium } = require('D:/Atharva/video-studio/node_modules/playwright-core');
const fs = require('fs');
const [out, url, tag = 'cur', ...sz] = process.argv.slice(2);
const sizes = sz.length ? sz : ['1920x1080', '1440x900', '1366x768', '1280x720', '1024x768', '768x1024', '375x812'];
(async () => {
  const b = await chromium.launch({ channel: 'msedge', headless: true });
  const rep = [];
  for (const s of sizes) {
    const [w, h] = s.split('x').map(Number);
    const ctx = await b.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
    const p = await ctx.newPage();
    const errs = [];
    p.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errs.push(m.text()) });
    p.on('pageerror', e => errs.push('PAGEERR ' + e.message));
    await p.route('**/assets/prism.js', async r => {
      const res = await r.fetch(); let t = await res.text();
      t = t.replace('window.FRPrism={', 'window.__G=function(){return G};window.FRPrism={');
      r.fulfill({ response: res, body: t, headers: { ...res.headers(), 'content-type': 'application/javascript' } });
    });
    await p.goto(url, { waitUntil: 'load' });
    await p.mouse.move(-10, -10);
    await p.waitForTimeout(3500);
    const samples = [];
    for (let i = 0; i < 6; i++) {
      samples.push(await p.evaluate(() => {
        const st = document.getElementById('hero').getBoundingClientRect();
        const R = e => { const r = e.getBoundingClientRect(); return { l: r.left - st.left, t: r.top - st.top, r: r.right - st.left, b: r.bottom - st.top } };
        const chips = [...document.querySelectorAll('#stIn li')].filter(li => getComputedStyle(li).display !== 'none' && +getComputedStyle(li).opacity > .05).map(li => R(li.firstChild));
        let ov = 0; for (let i = 0; i < chips.length; i++) for (let j = i + 1; j < chips.length; j++) { const a = chips[i], c = chips[j]; if (a.l < c.r && c.l < a.r && a.t < c.b && c.t < a.b) ov++ }
        return { ov, n: chips.length, chipTop: Math.min(...chips.map(c => c.t)), chipBot: Math.max(...chips.map(c => c.b)), chipMinL: Math.min(...chips.map(c => c.l)) };
      }));
      await p.waitForTimeout(1100);
    }
    const m = await p.evaluate(() => {
      const st = document.getElementById('hero').getBoundingClientRect();
      const R = e => { const r = e.getBoundingClientRect(); return { l: Math.round(r.left - st.left), t: Math.round(r.top - st.top), r: Math.round(r.right - st.left), b: Math.round(r.bottom - st.top) } };
      const G = window.__G ? window.__G() : null;
      const labs = [...document.querySelectorAll('#stOut li')].map(R);
      return {
        H: Math.round(st.height), W: Math.round(st.width), docW: document.documentElement.scrollWidth,
        h1: R(document.getElementById('hero-h')), form: R(document.getElementById('f')), hint: R(document.getElementById('hint')),
        hz: R(document.querySelector('.hz')), canvas: R(document.getElementById('pz')),
        apex: G && G.A ? Math.round(G.A.y) : null, base: G && G.L ? Math.round(Math.max(G.L.y, G.R.y)) : null, ph: G ? Math.round(G.h) : null,
        labTop: Math.min(...labs.map(l => l.t)), labBot: Math.max(...labs.map(l => l.b)), labR: Math.max(...labs.map(l => l.r)),
        tight: document.getElementById('stOut').classList.contains('tight')
      };
    });
    // layout shift
    const cls = await p.evaluate(() => new Promise(res => { let v = 0; try { new PerformanceObserver(l => { for (const e of l.getEntries()) if (!e.hadRecentInput) v += e.value }).observe({ type: 'layout-shift', buffered: true }) } catch (e) { } setTimeout(() => res(v), 300) }));
    m.cls = +cls.toFixed(4);
    m.chipOverlapSamples = samples.map(x => x.ov).join(',');
    m.chipTop = Math.round(Math.min(...samples.map(x => x.chipTop))); m.chipBot = Math.round(Math.max(...samples.map(x => x.chipBot))); m.chipMinL = Math.round(Math.min(...samples.map(x => x.chipMinL))); m.chipN = samples.map(x => x.n).join(',');
    m.gapHintApex = m.apex != null ? m.apex - m.hint.b : null;
    m.baseToHz = m.base != null ? m.hz.t - m.base : null;
    m.errs = errs;
    rep.push({ size: s, ...m });
    await p.screenshot({ path: `${out}/${tag}-${s}.png`, fullPage: w < 900 });
    await ctx.close();
  }
  await b.close();
  fs.writeFileSync(`${out}/${tag}-report.json`, JSON.stringify(rep, null, 1));
  for (const r of rep) console.log(r.size, 'H', r.H, 'hintB', r.hint.b, 'apex', r.apex, 'gap', r.gapHintApex, 'ph', r.ph, 'base', r.base, 'hzT', r.hz.t, 'base->hz', r.baseToHz, 'lab', r.labTop, r.labBot, 'labR', r.labR, r.tight ? 'tight' : '', 'chips', r.chipN, r.chipTop, r.chipBot, 'L', r.chipMinL, 'ov', r.chipOverlapSamples, 'cls', r.cls, 'docW', r.docW, 'errs', r.errs.length ? r.errs.join(' || ') : 0);
})();

