.L.streak{left:-10%;right:-10%;top:calc(var(--pcy) - 30px);height:60px;background:radial-gradient(closest-side,oklch(85% .05 260/.16),transparent)}
`, html: '<i class="L halo"></i><i class="L streak"></i>'
  },
  C: { // aurora: big soft diagonal spectral curtains across the upper field
    css: `
