.L.halo{left:calc(var(--pcx) - 420px);top:calc(var(--pcy) - 340px);width:840px;height:680px;background:radial-gradient(closest-side,oklch(36% .1 272/.5),transparent)}
`, html: '<i class="L au"></i><i class="L halo"></i>'
  }
};
(async () => {
  const b = await chromium.launch({ channel: 'msedge', headless: true });
  for (const k of process.argv.slice(5).length ? process.argv.slice(5) : Object.keys(C)) {
    const ctx = await b.newContext({ viewport: { width: W, height: Hh } });
    const p = await ctx.newPage();
    await p.route('**/assets/prism.js', async r => {
      const res = await r.fetch(); let t = await res.text();
      t = t.replace('window.FRPrism={', 'window.__G=function(){return G};window.FRPrism={');
      r.fulfill({ response: res, body: t, headers: { ...res.headers(), 'content-type': 'application/javascript' } });
    });
    await p.goto(url, { waitUntil: 'load' });
    await p.mouse.move(-10, -10);
    await p.waitForTimeout(3200);
    await p.addStyleTag({ content: base + C[k].css });
    await p.evaluate(html => {
      const G = window.__G(), h = document.getElementById('hero'), s = document.getElementById('stSky');
      s.insertAdjacentHTML('beforeend', html);
      const set = (n, v) => h.style.setProperty(n, Math.round(v) + 'px');
      set('--pcx', G.cx); set('--pcy', G.ay + G.h * .62); set('--pfx', G.fx); set('--pby', G.ay + G.h); set('--by', G.y0); set('--pix', G.Pin.x);
    }, C[k].html);
    await p.waitForTimeout(500);
    await p.screenshot({ path: `${out}/cand-${k}-${size}.png` });
    await ctx.close();
  }
  await b.close();
})();

