/* the backdrop: a dark room lit by the scene. A cool halo stands behind the prism, the spectrum
   bleeds color onto the wall where it lands, the failures glow warm on the left, and a hairline
   floor recedes under the prism. Soft light only, no stars. prism.js sets the --p* anchors;
   the defaults place the light for the no-JS still. Motion is transform and opacity only. */
.st-sky{--pcx:50%;--pcy:74%;--pfx:77%;--pby:86%;position:absolute;inset:0;z-index:0;pointer-events:none}
.st-sky i{position:absolute;display:block;pointer-events:none}
.st-sky .halo{left:calc(var(--pcx) - 560px);top:calc(var(--pcy) - 430px);width:1120px;height:860px;background:radial-gradient(closest-side,oklch(40% .13 272/.55),oklch(30% .1 276/.22) 50%,transparent);animation:bg-breathe 13s cubic-bezier(.45,0,.55,1) infinite alternate}
.st-sky .bleed{left:calc(var(--pfx) - 380px);top:calc(var(--pcy) - 390px);width:840px;height:780px;
 background:linear-gradient(180deg,transparent 4%,oklch(58% .2 28/.42) 22%,oklch(72% .16 70/.34) 38%,oklch(70% .17 150/.26) 56%,oklch(60% .16 245/.34) 74%,oklch(52% .2 290/.42) 90%,transparent);
 -webkit-mask-image:radial-gradient(closest-side,#000,transparent);mask-image:radial-gradient(closest-side,#000,transparent);animation:bg-drift 17s cubic-bezier(.45,0,.55,1) infinite alternate}
.st-sky .warm,.st-sky .warm-a{left:-280px;top:calc(var(--pcy) - 300px);width:780px;height:560px;animation:bg-sway 19s cubic-bezier(.45,0,.55,1) infinite alternate;transition:opacity .6s var(--ease)}
.st-sky .warm{background:radial-gradient(closest-side,oklch(40% .13 30/.38),transparent)}
.st-sky .warm-a{opacity:0;background:radial-gradient(closest-side,oklch(46% .11 72/.34),transparent)}
.stage[data-mode=audit] .st-sky .warm{opacity:0}.stage[data-mode=audit] .st-sky .warm-a{opacity:1}
.st-sky .floor{left:-60%;right:-60%;top:var(--pby);height:720px;margin-top:-118px;transform-origin:50% 0;transform:perspective(520px) rotateX(74deg);
 background-image:linear-gradient(oklch(85% .05 275/.2) 1px,transparent 1px),linear-gradient(90deg,oklch(85% .05 275/.2) 1px,transparent 1px);background-size:72px 72px;background-position:50% 0;
 -webkit-mask-image:radial-gradient(40% 72% at 50% 0,#000,transparent);mask-image:radial-gradient(40% 72% at 50% 0,#000,transparent)}
.stage.live .st-sky .bleed{animation:bg-in 1.6s .9s var(--ease) both,bg-drift 17s 2.5s cubic-bezier(.45,0,.55,1) infinite alternate}
.stage.idle .st-sky i,.stage.paused .st-sky i{animation-play-state:paused}
@keyframes bg-breathe{to{transform:scale(1.07)}}
@keyframes bg-drift{to{transform:translate3d(-14px,22px,0) scale(1.05)}}
@keyframes bg-sway{to{transform:translate3d(36px,-14px,0)}}
@keyframes bg-in{from{opacity:0}}

