const { chromium } = require('D:/Atharva/video-studio/node_modules/playwright-core');
const [url, size] = process.argv.slice(2);
const [w, h] = size.split('x').map(Number);
(async () => {
  const b = await chromium.launch({ channel: 'msedge', headless: true });
  const p = await (await b.newContext({ viewport: { width: w, height: h } })).newPage();
  await p.addInitScript(() => { window.__ls = []; new PerformanceObserver(l => { for (const e of l.getEntries()) window.__ls.push({ v: e.value, t: Math.round(e.startTime), src: e.sources.map(s => (s.node ? (s.node.nodeName + '#' + (s.node.id || '') + '.' + (s.node.className && s.node.className.baseVal === undefined ? s.node.className : '')) : '?') + ' ' + JSON.stringify(s.previousRect) + '->' + JSON.stringify(s.currentRect)) }) }).observe({ type: 'layout-shift', buffered: true }) });
  await p.goto(url, { waitUntil: 'load' }); await p.waitForTimeout(4000);
  console.log(JSON.stringify(await p.evaluate(() => window.__ls), null, 1));
  await b.close();
})();

