// Audit hover, reduced motion, no-JS and frame cost.
const { chromium } = require('D:/Atharva/video-studio/node_modules/playwright-core');
const [out, url, tag = 's'] = process.argv.slice(2);
const inject = async p => p.route('**/assets/prism.js', async r => {
  const res = await r.fetch(); let t = await res.text();
  t = t.replace('function loop(t){', 'window.__ft=[];function loop(t){var __a=performance.now();').replace('frame(t);raf=requestAnimationFrame(loop);', 'frame(t);window.__ft.push([performance.now()-__a,t]);raf=requestAnimationFrame(loop);');
  r.fulfill({ response: res, body: t, headers: { ...res.headers(), 'content-type': 'application/javascript' } });
});
(async () => {
  const b = await chromium.launch({ channel: 'msedge', headless: true, args: ['--enable-gpu-rasterization', '--ignore-gpu-blocklist'] });
  // audit hover
  for (const [w, h] of [[1440, 900], [1280, 720]]) {
    const p = await (await b.newContext({ viewport: { width: w, height: h } })).newPage();
    await p.goto(url, { waitUntil: 'load' }); await p.waitForTimeout(3000);
    await p.hover('#goA'); await p.waitForTimeout(1600);
    await p.screenshot({ path: `${out}/${tag}-audit-${w}x${h}.png` });
    await p.context().close();
  }
  // reduced motion
  {
    const p = await (await b.newContext({ viewport: { width: 1440, height: 900 }, reducedMotion: 'reduce' })).newPage();
    await p.goto(url, { waitUntil: 'load' }); await p.waitForTimeout(1500);
    const anim = await p.evaluate(() => [...document.querySelectorAll('#stSky i')].map(i => getComputedStyle(i).animationName).join(','));
    console.log('reduced-motion sky animations:', anim);
    await p.screenshot({ path: `${out}/${tag}-reduced-1440x900.png` });
    await p.context().close();
  }
  // no JS
  for (const [w, h] of [[1440, 900], [375, 812]]) {
    const p = await (await b.newContext({ viewport: { width: w, height: h }, javaScriptEnabled: false })).newPage();
    await p.goto(url, { waitUntil: 'load' }); await p.waitForTimeout(1200);
    await p.screenshot({ path: `${out}/${tag}-nojs-${w}x${h}.png`, fullPage: w < 900, clip: w < 900 ? { x: 0, y: 0, width: w, height: 1250 } : undefined });
    await p.context().close();
  }
  // frame cost, 8 s with the pointer moving
  {
    const p = await (await b.newContext({ viewport: { width: 1440, height: 900 } })).newPage();
    const errs = []; p.on('console', m => { if (m.type() === 'error') errs.push(m.text()) }); p.on('pageerror', e => errs.push(e.message));
    await inject(p);
    await p.goto(url, { waitUntil: 'load' }); await p.waitForTimeout(2500);
